package com.yuegang.zhihui.notification.api;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import com.yuegang.zhihui.notification.application.*;import com.yuegang.zhihui.notification.security.*;import jakarta.servlet.http.*;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController public final class NotificationController{private final NotificationService service;private final NotificationSecurity security;public NotificationController(NotificationService s,NotificationSecurity x){service=s;security=x;}@PostMapping("/internal/v1/notifications")ApiResponse<NotificationView>create(@Valid @RequestBody NotificationCommand c,HttpServletRequest r){security.service(r);return ok(service.create(c),r);}@GetMapping("/api/v1/notifications")ApiResponse<List<NotificationView>>list(HttpServletRequest r){return ok(service.list(security.user(r)),r);}@PutMapping("/api/v1/notifications/{id}/read")ApiResponse<Map<String,Boolean>>read(@PathVariable String id,HttpServletRequest r){service.read(security.user(r),id);return ok(Map.of("completed",true),r);}private static<T>ApiResponse<T>ok(T d,HttpServletRequest r){return ApiResponse.success(d,TraceIdResolver.resolve(r));}}
